<span class="c1"># Настройки DBSCAN</span>
<span class="n">dbscan_params</span> <span class="o">=</span> <span class="nb">dict</span><span class="p">(</span>
    <span class="n">eps</span><span class="o">=</span><span class="mf">0.01</span><span class="p">,</span>  <span class="c1"># Радиус окрестности</span>
    <span class="n">min_samples</span><span class="o">=</span><span class="mi">1000</span><span class="p">,</span>  <span class="c1"># Минимальное количество точек в окрестности</span>
    <span class="n">metric</span><span class="o">=</span><span class="s1">'euclidean'</span><span class="p">,</span>  <span class="c1"># Тип метрики</span>
    <span class="n">n_jobs</span><span class="o">=-</span><span class="mi">1</span>  <span class="c1"># Многопроцессорная обработка</span>
<span class="p">)</span>

<span class="c1"># Выполнение кластеризации</span>
<span class="n">dbscan_model</span> <span class="o">=</span> <span class="n">DBSCAN</span><span class="p">(</span><span class="o">**</span><span class="n">dbscan_params</span><span class="p">)</span>
<span class="n">labels</span> <span class="o">=</span> <span class="n">dbscan_model</span><span class="o">.</span><span class="n">fit_predict</span><span class="p">(</span><span class="n">subset_df</span><span class="p">)</span>

<span class="c1"># Добавляем метки кластеров</span>
<span class="n">subset_df</span><span class="p">[</span><span class="s1">'cluster_label'</span><span class="p">]</span> <span class="o">=</span> <span class="n">labels</span>

<span class="c1"># Анализируем результат</span>
<span class="n">unique_labels</span><span class="p">,</span> <span class="n">label_counts</span> <span class="o">=</span> <span class="n">np</span><span class="o">.</span><span class="n">unique</span><span class="p">(</span><span class="n">labels</span><span class="p">,</span> <span class="n">return_counts</span><span class="o">=</span><span class="kc">True</span><span class="p">)</span>
<span class="nb">print</span><span class="p">(</span><span class="n">np</span><span class="o">.</span><span class="n">column_stack</span><span class="p">([</span><span class="n">unique_labels</span><span class="p">,</span> <span class="n">label_counts</span><span class="p">]))</span>

<span class="c1"># Группируем данные по кластерам и выводим описание признаков delivery_delay_days и freight</span>
<span class="n">description_by_cluster</span> <span class="o">=</span> <span class="n">subset_df</span><span class="o">.</span><span class="n">groupby</span><span class="p">(</span><span class="s1">'cluster_label'</span><span class="p">)[[</span><span class="s1">'delivery_delay_days'</span><span class="p">,</span> <span class="s1">'freight'</span><span class="p">]]</span><span class="o">.</span><span class="n">describe</span><span class="p">()</span>


<span class="c1"># Боксплот для delivery_delay_days</span>
<span class="n">plt</span><span class="o">.</span><span class="n">figure</span><span class="p">(</span><span class="n">figsize</span><span class="o">=</span><span class="p">(</span><span class="mi">10</span><span class="p">,</span> <span class="mi">6</span><span class="p">))</span>
<span class="n">sns</span><span class="o">.</span><span class="n">boxplot</span><span class="p">(</span><span class="n">x</span><span class="o">=</span><span class="s1">'cluster_label'</span><span class="p">,</span> <span class="n">y</span><span class="o">=</span><span class="s1">'delivery_delay_days'</span><span class="p">,</span> <span class="n">data</span><span class="o">=</span><span class="n">subset_df</span><span class="p">)</span>
<span class="n">plt</span><span class="o">.</span><span class="n">title</span><span class="p">(</span><span class="s1">'Boksplot для delivery_delay_days по кластерам'</span><span class="p">)</span>
