<span class="n">sns</span><span class="o">.</span><span class="n">violinplot</span><span class="p">(</span><span class="n">x</span><span class="o">=</span><span class="s1">'cluster_label'</span><span class="p">,</span> <span class="n">y</span><span class="o">=</span><span class="s1">'delivery_delay_days'</span><span class="p">,</span> <span class="n">data</span><span class="o">=</span><span class="n">subset_df</span><span class="p">)</span>
