<span class="n">sns</span><span class="o">.</span><span class="n">violinplot</span><span class="p">(</span><span class="n">x</span><span class="o">=</span><span class="s1">'cluster_label'</span><span class="p">,</span> <span class="n">y</span><span class="o">=</span><span class="s1">'freight'</span><span class="p">,</span> <span class="n">data</span><span class="o">=</span><span class="n">subset_df</span><span class="p">)</span>
<span class="n">plt</span><span class="o">.</span><span class="n">title</span><span class="p">(</span><span class="s1">'Violin plot для freight по кластерам'</span><span class="p">)</span>
<span class="n">plt</span><span class="o">.</span><span class="n">show</span><span class="p">()</span>
