      <div class="jp-Cell jp-CodeCell jp-Notebook-cell jp-mod-noOutputs">
        <div class="jp-Cell-inputWrapper" tabindex="0">
          <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
