            <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
              <div class="cm-editor cm-s-jupyter">
                <div class="highlight hl-ipython3">
                  <pre><span class="k">def</span> <span class="nf">normalize_dataframe</span><span class="p">(</span><span class="n">df</span><span class="p">,</span> <span class="n">columns</span><span class="p">):</span>
    <span class="n">df</span><span class="o">.</span><span class="n">dropna</span><span class="p">(</span><span class="n">inplace</span><span class="o">=</span><span class="kc">True</span><span class="p">)</span>
    <span class="c1"># Сохраняем исходный индекс</span>
    <span class="n">index_copy</span> <span class="o">=</span> <span class="n">df</span><span class="o">.</span><span class="n">index</span><span class="o">.</span><span class="n">copy</span><span class="p">()</span>
    
    <span class="c1"># Заполняем пропуски нулевыми значениями</span>
    <span class="n">df</span><span class="o">.</span><span class="n">fillna</span><span class="p">(</span><span class="mi">0</span><span class="p">,</span> <span class="n">inplace</span><span class="o">=</span><span class="kc">True</span><span class="p">)</span>
    
    <span class="c1"># Нормализация данных</span>
    <span class="n">scaler</span> <span class="o">=</span> <span class="n">MinMaxScaler</span><span class="p">()</span>
    <span class="n">normalized_columns</span> <span class="o">=</span> <span class="p">[</span><span class="n">col</span> <span class="k">for</span> <span class="n">col</span> <span class="ow">in</span> <span class="n">columns</span><span class="p">]</span>
    <span class="n">normalized_data</span> <span class="o">=</span> <span class="n">scaler</span><span class="o">.</span><span class="n">fit_transform</span><span class="p">(</span><span class="n">df</span><span class="p">[</span><span class="n">normalized_columns</span><span class="p">])</span>
    
    <span class="c1"># Создаем новый датафрейм с нормализованными данными и восстановленным индексом</span>
    <span class="n">normalized_df</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">DataFrame</span><span class="p">(</span><span class="n">normalized_data</span><span class="p">,</span> <span class="n">columns</span><span class="o">=</span><span class="n">normalized_columns</span><span class="p">,</span> <span class="n">index</span><span class="o">=</span><span class="n">index_copy</span><span class="p">)</span>
    
    <span class="k">return</span> <span class="n">normalized_df</span>
</pre>
                </div>
