      <div class="jp-Cell jp-CodeCell jp-Notebook-cell jp-mod-noOutputs">
        <div class="jp-Cell-inputWrapper" tabindex="0">
          <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
          <div class="jp-InputArea jp-Cell-inputArea">
            <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
              <div class="cm-editor cm-s-jupyter">
                <div class="highlight hl-ipython3">
                  <pre><span class="k">def</span> <span class="nf">boxploter</span><span class="p">(</span><span class="n">df_clustered</span><span class="p">,</span> <span class="n">columns</span><span class="p">):</span>
    <span class="c1"># Ограничимся только переданными колонками</span>
    <span class="n">features_to_plot</span> <span class="o">=</span> <span class="n">columns</span>
    
    <span class="c1"># Определяем количество строк и столбцов сетки для размещения графиков</span>
    <span class="n">num_plots</span> <span class="o">=</span> <span class="nb">len</span><span class="p">(</span><span class="n">features_to_plot</span><span class="p">)</span>
    <span class="n">rows</span> <span class="o">=</span> <span class="n">num_plots</span> <span class="o">//</span> <span class="mi">3</span> <span class="o">+</span> <span class="p">(</span><span class="n">num_plots</span> <span class="o">%</span> <span class="mi">3</span> <span class="o">&gt;</span> <span class="mi">0</span><span class="p">)</span>
    <span class="n">fig</span><span class="p">,</span> <span class="n">axes</span> <span class="o">=</span> <span class="n">plt</span><span class="o">.</span><span class="n">subplots</span><span class="p">(</span><span class="n">rows</span><span class="p">,</span> <span class="mi">3</span><span class="p">,</span> <span class="n">figsize</span><span class="o">=</span><span class="p">(</span><span class="mi">15</span><span class="p">,</span> <span class="n">rows</span> <span class="o">*</span> <span class="mi">5</span><span class="p">))</span>
    <span class="n">axes</span> <span class="o">=</span> <span class="n">axes</span><span class="o">.</span><span class="n">flatten</span><span class="p">()</span>

    <span class="c1"># Рисуем boxplots для каждого признака</span>
    <span class="k">for</span> <span class="n">i</span><span class="p">,</span> <span class="n">feature</span> <span class="ow">in</span> <span class="nb">enumerate</span><span class="p">(</span><span class="n">features_to_plot</span><span class="p">):</span>
        <span class="n">ax</span> <span class="o">=</span> <span class="n">axes</span><span class="p">[</span><span class="n">i</span><span class="p">]</span>
        <span class="n">sns</span><span class="o">.</span><span class="n">boxplot</span><span class="p">(</span><span class="n">x</span><span class="o">=</span><span class="s1">'cluster_label'</span><span class="p">,</span> <span class="n">y</span><span class="o">=</span><span class="n">feature</span><span class="p">,</span> <span class="n">data</span><span class="o">=</span><span class="n">df_clustered</span><span class="p">,</span> <span class="n">ax</span><span class="o">=</span><span class="n">ax</span><span class="p">)</span>
        <span class="n">ax</span><span class="o">.</span><span class="n">set_title</span><span class="p">(</span><span class="n">feature</span><span class="p">)</span>

    <span class="c1"># Если есть неиспользованные ячейки, уберем их</span>
    <span class="k">for</span> <span class="n">j</span> <span class="ow">in</span> <span class="nb">range</span><span class="p">(</span><span class="n">num_plots</span><span class="p">,</span> <span class="nb">len</span><span class="p">(</span><span class="n">axes</span><span class="p">)):</span>
        <span class="n">fig</span><span class="o">.</span><span class="n">delaxes</span><span class="p">(</span><span class="n">axes</span><span class="p">[</span><span class="n">j</span><span class="p">])</span>

    <span class="n">plt</span><span class="o">.</span><span class="n">tight_layout</span><span class="p">()</span>
    <span class="n">plt</span><span class="o">.</span><span class="n">show</span><span class="p">()</span>
</pre>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
      <div class="jp-Cell jp-CodeCell jp-Notebook-cell">
        <div class="jp-Cell-inputWrapper" tabindex="0">
          <div class="jp-Collapser jp-InputCollapser jp-Cell-inputCollapser"></div>
          <div class="jp-InputArea jp-Cell-inputArea">
            <div class="jp-CodeMirrorEditor jp-Editor jp-InputArea-editor" data-type="inline">
              <div class="cm-editor cm-s-jupyter">
                <div class="highlight hl-ipython3">
                  <pre><span class="k">def</span> <span class="nf">cluster_describer</span><span class="p">(</span><span class="n">df_original</span><span class="p">,</span> <span class="n">columns_for_clustering</span><span class="p">,</span> <span class="n">n_clust</span><span class="p">):</span>
    <span class="c1"># Шаг 1: Удаляем строки с пропусками сразу перед нормализацией</span>
    <span class="n">df_cleaned</span> <span class="o">=</span> <span class="n">df_original</span><span class="o">.</span><span class="n">dropna</span><span class="p">(</span><span class="n">subset</span><span class="o">=</span><span class="n">columns_for_clustering</span><span class="p">)</span>
    
    <span class="c1"># Шаг 2: Нормализация данных только на очищённом датафрейме</span>
    <span class="n">scaler</span> <span class="o">=</span> <span class="n">StandardScaler</span><span class="p">()</span>
    <span class="n">normalized_data</span> <span class="o">=</span> <span class="n">scaler</span><span class="o">.</span><span class="n">fit_transform</span><span class="p">(</span><span class="n">df_cleaned</span><span class="p">[</span><span class="n">columns_for_clustering</span><span class="p">])</span>
    
    <span class="c1"># Преобразование обратно в DataFrame</span>
    <span class="n">df_normalized</span> <span class="o">=</span> <span class="n">pd</span><span class="o">.</span><span class="n">DataFrame</span><span class="p">(</span><span class="n">normalized_data</span><span class="p">,</span> <span class="n">columns</span><span class="o">=</span><span class="n">columns_for_clustering</span><span class="p">,</span> <span class="n">index</span><span class="o">=</span><span class="n">df_cleaned</span><span class="o">.</span><span class="n">index</span><span class="p">)</span>
    
    <span class="c1"># Шаг 3: Кластеризация на нормализованных данных</span>
    <span class="n">kmeans</span> <span class="o">=</span> <span class="n">KMeans</span><span class="p">(</span><span class="n">n_clusters</span><span class="o">=</span><span class="n">n_clust</span><span class="p">,</span> <span class="n">random_state</span><span class="o">=</span><span class="mi">42</span><span class="p">)</span>
    <span class="n">clusters</span> <span class="o">=</span> <span class="n">kmeans</span><span class="o">.</span><span class="n">fit_predict</span><span class="p">(</span><span class="n">df_normalized</span><span class="p">)</span>
    
    <span class="c1"># Шаг 4: Присваиваем номера кластеров очищенному датафрейму</span>
    <span class="n">df_clustered</span> <span class="o">=</span> <span class="n">df_cleaned</span><span class="o">.</span><span class="n">copy</span><span class="p">()</span>
    <span class="n">df_clustered</span><span class="p">[</span><span class="s1">'cluster_label'</span><span class="p">]</span> <span class="o">=</span> <span class="n">clusters</span>
    
    <span class="c1"># Агрегируем по признакам, участвующим в кластеризации</span>
    <span class="n">grouped_stats</span> <span class="o">=</span> <span class="n">df_clustered</span><span class="o">.</span><span class="n">groupby</span><span class="p">(</span><span class="s1">'cluster_label'</span><span class="p">)[</span><span class="n">columns_for_clustering</span><span class="p">]</span><span class="o">.</span><span class="n">agg</span><span class="p">([</span>
        <span class="s1">'mean'</span><span class="p">,</span> <span class="s1">'std'</span><span class="p">,</span> <span class="s1">'median'</span><span class="p">,</span> <span class="s1">'min'</span><span class="p">,</span> <span class="s1">'max'</span>
    <span class="p">])</span>
    
    <span class="c1"># Выводим статистику</span>
    <span class="nb">print</span><span class="p">(</span><span class="n">grouped_stats</span><span class="p">)</span>
    <span class="n">boxploter</span><span class="p">(</span><span class="n">df_clustered</span><span class="p">,</span> <span class="n">columns_for_clustering</span><span class="p">)</span>


<span class="n">cluster_describer</span><span class="p">(</span><span class="n">customers_ext</span><span class="p">,</span> <span class="p">[</span><span class="s1">'delivery_delay_days'</span><span class="p">,</span> <span class="s1">'freight'</span><span class="p">],</span> <span class="mi">7</span><span class="p">)</span>
</pre>
                </div>
              </div>
            </div>
          </div>
        </div>
        <div class="jp-Cell-outputWrapper">
          <div class="jp-Collapser jp-OutputCollapser jp-Cell-outputCollapser"></div>
          <div class="jp-OutputArea jp-Cell-outputArea">
