<span class="n">train_test_df</span><span class="p">[</span><span class="s1">'cluster_label'</span><span class="p">]</span> <span class="o">=</span> <span class="n">kmeans</span><span class="o">.</span><span class="n">fit_predict</span><span class="p">(</span><span class="n">train_test_df</span><span class="p">[</span><span class="n">column_names</span><span class="p">])</span>

<span class="c1"># Теперь проверьте, что колонка существует</span>
