    <span class="n">train_test_df</span><span class="o">.</span><span class="n">groupby</span><span class="p">(</span><span class="s1">'cluster_label'</span><span class="p">)[</span><span class="s1">'lost_seller'</span><span class="p">]</span>
    <span class="o">.</span><span class="n">agg</span><span class="p">([</span><span class="s1">'sum'</span><span class="p">,</span> <span class="s1">'count'</span><span class="p">])</span>
    <span class="o">.</span><span class="n">rename</span><span class="p">(</span><span class="n">columns</span><span class="o">=</span><span class="p">{</span><span class="s1">'sum'</span><span class="p">:</span> <span class="s1">'lost_count'</span><span class="p">,</span> <span class="s1">'count'</span><span class="p">:</span> <span class="s1">'total_count'</span><span class="p">})</span>
<span class="p">)</span>

<span class="c1"># Теперь рассчитываем доли</span>
